
import { prisma } from "../prisma"

export async function getProfessoresDisponibilidade() {
    const professorDiaSemana = await prisma.professor.findMany({
        include: {
            disponibilidades:{
                where: {
                    dia : {
                        nome_dia: 'Segunda-Feira'
                    }
                }
            }
        }
    })
    return professorDiaSemana
}

